servers.onUp:
function onUp() {
  let s = loadState();
  if (!s.phase) {
    s = { phase: 'idle', txId: 0, votes: {}, acks: {},
          committed: 0, aborted: 0 };
  }
  dumpState(s);
}

servers.onTimer:
function onTimer(tick) {
  let s = loadState();
  s.tick = tick;

  // Start a new transaction every 25 ticks
  if (s.phase === 'idle' && tick > 0 && tick % 25 === 0) {
    s.txId++;
    s.phase = 'prepare';
    s.votes = {};
    s.acks = {};
    for (const id of allServerIds) {
      if (id !== serverId) {
        sendMessage(id, {
          type: 'PREPARE', txId: s.txId,
          data: 'write_X=' + s.txId
        });
      }
    }
  }

  // Timeout: if still in prepare/commit after 12 ticks, abort
  if (s.phase === 'prepare' && s.phaseStart && tick - s.phaseStart > 12) {
    s.phase = 'abort';
    for (const id of allServerIds) {
      if (id !== serverId) {
        sendMessage(id, { type: 'ABORT', txId: s.txId });
      }
    }
    s.aborted++;
    s.phase = 'idle';
  }

  if (s.phase === 'prepare') {
    s.phaseStart = s.phaseStart || tick;
  }

  dumpState(s);
}

servers.onMessage:
function onMessage(message) {
  let s = loadState();
  const m = message.payload;

  if (m.type === 'VOTE_COMMIT' && s.phase === 'prepare') {
    s.votes[message.from] = 'yes';
    // Check if all participants voted
    const expected = allServerIds.filter(id => id !== serverId);
    const allVoted = expected.every(id => s.votes[id] !== undefined);
    if (allVoted) {
      const allYes = expected.every(id => s.votes[id] === 'yes');
      if (allYes) {
        s.phase = 'committed';
        for (const id of expected) {
          sendMessage(id, { type: 'COMMIT', txId: s.txId });
        }
        s.committed++;
      } else {
        s.phase = 'aborted';
        for (const id of expected) {
          sendMessage(id, { type: 'ABORT', txId: s.txId });
        }
        s.aborted++;
      }
      s.phaseStart = null;
      s.phase = 'idle';
    }
  }

  if (m.type === 'VOTE_ABORT' && s.phase === 'prepare') {
    s.votes[message.from] = 'no';
    // Immediately abort
    s.phase = 'aborted';
    const expected = allServerIds.filter(id => id !== serverId);
    for (const id of expected) {
      sendMessage(id, { type: 'ABORT', txId: s.txId });
    }
    s.aborted++;
    s.phaseStart = null;
    s.phase = 'idle';
  }

  if (m.type === 'ACK') {
    s.acks[message.from] = m.txId;
  }

  dumpState(s);
}

servers.onUp:
function onUp() {
  let s = loadState();
  if (!s.status) {
    s = { status: 'ready', data: null,
          pendingTx: null, history: [] };
  }
  dumpState(s);
}

servers.onTimer:
function onTimer(tick) {
  let s = loadState();
  s.tick = tick;
  dumpState(s);
}

servers.onMessage:
function onMessage(message) {
  let s = loadState();
  const m = message.payload;

  if (m.type === 'PREPARE') {
    s.status = 'voting';
    s.pendingTx = m.txId;
    s.pendingData = m.data;
    // Vote YES (simulate: always agree)
    sendMessage(message.from, {
      type: 'VOTE_COMMIT', txId: m.txId
    });
    s.status = 'voted_yes';
  }

  if (m.type === 'COMMIT' && s.pendingTx === m.txId) {
    s.data = s.pendingData;
    s.history.push('TX' + m.txId + ':commit');
    s.pendingTx = null;
    s.pendingData = null;
    s.status = 'ready';
    sendMessage(message.from, {
      type: 'ACK', txId: m.txId
    });
  }

  if (m.type === 'ABORT' && s.pendingTx === m.txId) {
    s.history.push('TX' + m.txId + ':abort');
    s.pendingTx = null;
    s.pendingData = null;
    s.status = 'ready';
    sendMessage(message.from, {
      type: 'ACK', txId: m.txId
    });
  }

  dumpState(s);
}
